import { describe, expect, test } from "bun:test";
import { barrelSource } from "./generate-types.js";

describe("barrelSource", () => {
  test("sorts generated types and re-exports the shared ones", () => {
    expect(barrelSource(["Message", "Device", "MessageType"])).toBe(
      "// AUTO-GENERATED by scripts/generate-types.ts — do not edit.\n" +
        "// Re-exports every ts-rs generated type and the hand-written shared types.\n" +
        "\n" +
        'export type { Device } from "./Device";\n' +
        'export type { Message } from "./Message";\n' +
        'export type { MessageType } from "./MessageType";\n' +
        "\n" +
        'export type { ExtensionOptions, StatusData } from "../shared-types.js";\n',
    );
  });

  test("handles an empty set", () => {
    const source = barrelSource([]);
    expect(source).toContain(
      'export type { ExtensionOptions, StatusData } from "../shared-types.js";',
    );
    expect(source).not.toContain('from "./"');
  });
});
